import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { distanceM, projectOntoSegment } from '../src/index.js';

/**
 * Cross-language check against fixtures/geodesy-golden.json, generated by
 * pipeline/scripts/make_geodesy_golden.py (seed 20261024). The same file is read by the Python
 * suite, so core and the pipeline provably agree: within 1 mm of GeographicLib (GRS80) and within
 * 1e-6 m of the Python port.
 */
type Pt = readonly [number, number];
type Golden = {
  readonly distance: readonly { a: Pt; b: Pt; geodesicM: number; pythonM: number }[];
  readonly projection: readonly {
    p: Pt;
    a: Pt;
    b: Pt;
    t: number;
    crossTrackM: number;
    alongM: number;
  }[];
};

const golden = JSON.parse(
  readFileSync(new URL('../../../fixtures/geodesy-golden.json', import.meta.url), 'utf8'),
) as Golden;

const ll = (p: Pt): { lat: number; lon: number } => ({ lat: p[0], lon: p[1] });

describe('geodesy golden file (shared with the Python pipeline)', () => {
  it('has the documented size', () => {
    expect(golden.distance).toHaveLength(2000);
    expect(golden.projection).toHaveLength(500);
  });

  it('distanceM is within 1 mm of GeographicLib and 1e-6 m of Python for every pair', () => {
    for (const c of golden.distance) {
      const d = distanceM(ll(c.a), ll(c.b));
      expect(Math.abs(d - c.geodesicM)).toBeLessThan(1e-3);
      expect(Math.abs(d - c.pythonM)).toBeLessThan(1e-6);
    }
  });

  it('projectOntoSegment agrees with Python: t to 1e-9, distances to 1e-6 m', () => {
    for (const c of golden.projection) {
      const r = projectOntoSegment(ll(c.p), ll(c.a), ll(c.b));
      expect(Math.abs(r.t - c.t)).toBeLessThan(1e-9);
      expect(Math.abs(r.crossTrackM - c.crossTrackM)).toBeLessThan(1e-6);
      expect(Math.abs(r.alongSegmentM - c.alongM)).toBeLessThan(1e-6);
    }
  });
});
